def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = [list(sorted_intervals[0])]

    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    edge_set = set(edges)

    adj = {n: [] for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for u, v in edge_set:
        adj[u].append(v)
        in_degree[v] += 1

    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (missing '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and (
            (value[0] == '"' and value[-1] == '"')
            or (value[0] == "'" and value[-1] == "'")
        ):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    lines = text.split('\n')

    result = []
    data_lines = []
    has_data = False

    for line in lines:
        if line == '':
            if has_data:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    return result
                result.append(data)
            data_lines = []
            has_data = False
        elif line.startswith(':'):
            continue
        else:
            if ':' in line:
                idx = line.index(':')
                field = line[:idx]
                value = line[idx + 1:]
                if value.startswith(' '):
                    value = value[1:]
            else:
                field = line
                value = ''

            if field == 'data':
                data_lines.append(value)
                has_data = True

    return result

import math


def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0
    # Use logarithmic comparison to avoid constructing 2**attempt as a huge integer.
    # log2(base * 2**attempt) == log2(base) + attempt
    log_result = math.log2(base) + attempt
    if log_result >= math.log2(cap):
        return float(cap)
    # Result is guaranteed < cap (finite), so 2.0**log_result won't overflow.
    return 2.0 ** log_result

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError("queued reservation exceeds the whole budget")

    remaining_slots = slots - len(active)
    remaining_tokens = budget - sum(active)

    admitted = []
    i = 0
    for r in queued:
        if remaining_slots > 0 and r <= remaining_tokens:
            admitted.append(r)
            remaining_slots -= 1
            remaining_tokens -= r
            i += 1
        else:
            break

    remaining = queued[i:]
    return (admitted, remaining)
